[workspace.package]
version = "1.6.0"
edition = "2024"
description = "Dynamo Inference Framework"
authors = ["NVIDIA Inc. <sw-dl-dynamo@nvidia.com>"]
license = "Apache-2.0"
homepage = "https://github.com/ai-dynamo/dynamo"
repository = "https://github.com/ai-dynamo/dynamo.git"
keywords = ["llm", "genai", "inference", "nvidia", "distributed"]

[workspace.dependencies]
dynamo-custom-policy-builtin = { path = "lib/router-plugins/builtin", version = "1.6.0" }
# Published separately by https://github.com/ai-dynamo/aisimulate.
aisimulate-core = { version = "=0.13.0-dev.202609300000000061" }

# Local crates
dynamo-runtime = { path = "lib/runtime", version = "1.6.0" }
dynamo-llm = { path = "lib/llm", version = "1.6.0" }
dynamo-rl = { path = "lib/rl", version = "1.6.0" }
dynamo-tokenizers = { version = "=2.0.0" }
dynamo-renderer = { version = "=6.0.0" }
dynamo-tokens = { path = "lib/tokens", version = "1.6.0" }
dynamo-truthy = { path = "lib/truthy", version = "1.6.0" }
dynamo-data-gen = { path = "lib/data-gen", version = "1.6.0" }
dynamo-kv-hashing = { path = "lib/kv-hashing", version = "1.6.0" }
dynamo-memory = { path = "lib/memory", version = "1.6.0" }
dynamo-mocker = { path = "lib/mocker", version = "1.6.0" }
dynamo-kv-router = { path = "lib/kv-router", version = "1.6.0" }
dynamo-protocols = { version = "=6.1.0" }
dynamo-parsers = { version = "9.0.0" }

# Published on crates.io. To see all available versions:
#   web:          https://crates.io/crates/dynamo-parsers-v2/versions
#   sparse index: curl https://index.crates.io/dy/na/dynamo-parsers-v2   (one JSON line per release; read the "vers" field)
dynamo-parsers-v2 = { version = "0.5.3" }
dynamo-backend-common = { path = "lib/backend-common", version = "1.6.0" }
dynamo-sidecar-common = { path = "lib/sidecar/common", version = "1.6.0" }


# kvbm
kvbm-common = { path = "lib/kvbm-common", version = "1.6.0" }
kvbm-config = { path = "lib/kvbm-config", version = "1.6.0" }
kvbm-consolidator = { path = "lib/kvbm-consolidator", version = "1.6.0" }
kvbm-engine = { path = "lib/kvbm-engine", version = "1.6.0" }
kvbm-kernels = { path = "lib/kvbm-kernels", version = "1.6.0" }
kvbm-logical = { path = "lib/kvbm-logical", version = "1.6.0" }
kvbm-physical = { path = "lib/kvbm-physical", version = "1.6.0" }

# velo
velo = { version = "0.12.0" }

# External dependencies
anyhow = { version = "1" }
lru = { version = "0.16" }
async-nats = { version = "0.49.1", features = ["service"] }
async-stream = { version = "0.3" }
async-trait = { version = "0.1" }
blake3 = { version = "1.8.7" }
bytes = { version = "1.9" }
chrono = { version = "0.4", default-features = false, features = [
    "alloc",
    "std",
    "clock",
    "now",
    "serde",
] }
cudarc = { version = "=0.19.8", features = ["cuda-version-from-build-system", "fallback-latest"] }
dashmap = { version = "6.1" }
moka = { version = "0.12", features = ["future"] }
derive_builder = { version = "0.20" }
derive-getters = { version = "0.5" }
either = { version = "1.13", features = ["serde"] }
etcd-client = { version = "0.17.0", features = ["tls"] }
futures = { version = "0.3" }
futures-util = { version = "0.3.32" }
fs4 = { version = "0.13.1" }
hf-hub = { version = "0.4.2", default-features = false }

# ModelExpress for model downloading
modelexpress-client = { version = "0.6.0" }
modelexpress-common = { version = "0.6.0" }

humantime = { version = "2.2.0" }
indexmap = { version = "2" }
ipnet = { version = "2" }
libc = { version = "0.2" }
oneshot = { version = "0.1.13", features = ["std", "async"] }
ordered-float = "4"
